std::string pageLanguageJson() {
    std::string out = "{";
    const char* parts[] = {kEn, kDe, kEs, kFr, kIt, kPt, kNl, kJa};
    bool first = true;
    for (const char* part : parts) {
        if (!first) {
            out += ",";
        }
        first = false;
        out += part;
    }
    out += "}";
    return out;
}

